    [Fact]
    public void SerializesEmptyMetadata()
    {
        var metadata = new Metadata();

        var json = _serializer.Serialize(metadata);

        Assert.NotNull(json);
    }

    [Fact]
    public void DeserializesEmptyObject()
    {
        var json = "{}";

        var metadata = _serializer.Deserialize<Metadata>(json);

        Assert.NotNull(metadata);
    }

    [Fact]
    public void DeserializesAdditionalStringProperties()
    {
        var json = "{\"createdAt\":\"2024-01-01T00:00:00Z\",\"customField\":\"hello\"}";
        var metadata = _serializer.Deserialize<Metadata>(json);
        Assert.NotNull(metadata);
        Assert.NotNull(metadata!.AdditionalProperties);
        Assert.True(metadata.AdditionalProperties!.ContainsKey("customField"));
    }

    [Fact]
    public void RoundTripPreservesAdditionalProperties()
    {
        var metadata = new Metadata();
        metadata.AdditionalProperties = new Dictionary<string, object>
        {
            ["customField"] = "hello",
            ["anotherField"] = "world",
        };
        var json = _serializer.Serialize(metadata);
        var deserialized = _serializer.Deserialize<Metadata>(json);
        Assert.NotNull(deserialized);
        Assert.NotNull(deserialized!.AdditionalProperties);
        Assert.Equal(2, deserialized.AdditionalProperties!.Count);
    }

    [Fact]
    public void AdditionalPropertiesContainStringValues()
    {
        var metadata = new Metadata();
        metadata.AdditionalProperties = new Dictionary<string, object> { ["key"] = "value" };
        Assert.Equal("value", metadata.AdditionalProperties["key"]);
    }

    [Fact]
    public void DeclaredDevDependenciesAreInTheProjectManifest()
    {
        // A generated test may reference a package that only the generator knows
        // about, and every real client keep-lists its own test project file, so
        // the two silently drift apart and the suite dies at compile time with an
        // unresolved using. The generator-owned manifest lists what the generated
        // tests need; this fails first, naming the file.
        // dotnet test runs the host from the build output directory, so walk up
        // to the project root rather than assuming the working directory.
        var root = new DirectoryInfo(AppContext.BaseDirectory);
        while (
            root is not null
            && !File.Exists(Path.Combine(root.FullName, ".openapi-generator", "DEV-DEPENDENCIES"))
        )
        {
            root = root.Parent;
        }
        Assert.True(
            root is not null,
            ".openapi-generator/DEV-DEPENDENCIES must exist at the project root"
        );
        var declared = Path.Combine(root!.FullName, ".openapi-generator", "DEV-DEPENDENCIES");
        var manifest = File.ReadAllText(Path.Combine(root.FullName, "PetstoreClient.Test.csproj"));
        foreach (var line in File.ReadAllLines(declared))
        {
            var entry = line.Trim();
            if (entry.Length == 0)
            {
                continue;
            }
            var name = entry.Split(' ')[0];
            Assert.True(
                manifest.Contains($"Include=\"{name}\"", StringComparison.Ordinal),
                $"PetstoreClient.Test.csproj does not declare {name}, which "
                    + ".openapi-generator/DEV-DEPENDENCIES lists as required by the generated "
                    + "tests. Add it as a PackageReference; the generator cannot edit a "
                    + "keep-listed manifest."
            );
        }
    }
